-- Test-only physical-envelope helper for the compressed derived-cache
-- contract: builds and parses the versioned envelope that wraps compressible
-- generated bytes on disk, and injects faithful host codec callbacks into a
-- fake backend. Production encoding lives in CacheFs; this module only lets
-- suites plant and inspect physical bytes without re-deriving the layout in
-- every file. Never required by production code.

local CacheEnvelope = {}

-- Envelope tag, codec identifiers, and header footprint of the physical form
-- under test: 4-byte tag, 1-byte codec, little-endian 32-bit decoded length,
-- and a 20-byte binary digest of the logical payload.
CacheEnvelope.MAGIC = "PDC1"
CacheEnvelope.HEADER_SIZE = 29
CacheEnvelope.CODEC_LZ4 = 1
CacheEnvelope.CODEC_ZLIB = 2
-- Structured failure the storage layer reports for a damaged envelope.
CacheEnvelope.DECODE_FAILED = "CACHE_DECODE_FAILED"

local CODEC_FORMATS = {
  [CacheEnvelope.CODEC_LZ4] = "lz4",
  [CacheEnvelope.CODEC_ZLIB] = "zlib",
}

---@param value integer
---@return string
local function encodeU32LE(value)
  assert(value >= 0 and value < 2 ^ 32 and value % 1 == 0, "decoded length must fit in 32 bits")
  local bytes = {}
  for _ = 1, 4 do
    bytes[#bytes + 1] = string.char(value % 256)
    value = math.floor(value / 256)
  end
  return table.concat(bytes)
end

---@param bytes string
---@return integer
local function decodeU32LE(bytes)
  local a, b, c, d = bytes:byte(1, 4)
  assert(a ~= nil and b ~= nil and c ~= nil and d ~= nil, "decoded length needs four bytes")
  return a + b * 256 + c * 65536 + d * 16777216
end

-- Attaches host compression callbacks to a fake backend so CacheFs can
-- encode through the injected seam instead of the bare fake. Every callback
-- delegates to the LÖVE 11.5 host, which the test process always provides.
---@param backend table<string, unknown>
---@return table<string, unknown>
function CacheEnvelope.attachHostCodecs(backend)
  assert(type(backend) == "table", "codec callbacks attach to a backend table")
  -- Tolerate both `backend:compress(format, bytes)` and
  -- `backend.compress(format, bytes)`; the suites pin behavior, not arity.
  backend.compress = function(first, second, third)
    local format, bytes = first, second
    if third ~= nil then
      format, bytes = second, third
    end
    assert(type(format) == "string" and type(bytes) == "string", "host compress takes a format and bytes")
    local compressed = love.data.compress("string", format, bytes)
    assert(type(compressed) == "string", "host compression must return a string")
    return compressed
  end
  backend.decompress = function(first, second, third)
    local format, bytes = first, second
    if third ~= nil then
      format, bytes = second, third
    end
    assert(type(format) == "string" and type(bytes) == "string", "host decompress takes a format and bytes")
    local decompressed = love.data.decompress("string", format, bytes)
    assert(type(decompressed) == "string", "host decompression must return a string")
    return decompressed
  end
  backend.hashSha1 = function(first, second)
    local bytes = second ~= nil and second or first
    assert(type(bytes) == "string", "host hashing takes bytes")
    local digest = love.data.hash("sha1", bytes)
    assert(type(digest) == "string" and #digest == 20, "host sha1 must be a 20-byte binary digest")
    return digest
  end
  return backend
end

-- Wraps logical bytes in a canonical envelope using the host codecs.
---@param codecByte integer
---@param logicalBytes string
---@return string
function CacheEnvelope.build(codecByte, logicalBytes)
  local format = CODEC_FORMATS[codecByte]
  assert(format ~= nil, "unknown envelope codec: " .. tostring(codecByte))
  assert(type(logicalBytes) == "string", "envelope input must be a string")
  local compressed = love.data.compress("string", format, logicalBytes)
  assert(type(compressed) == "string", "host compression must return a string")
  local digest = love.data.hash("sha1", logicalBytes)
  assert(type(digest) == "string" and #digest == 20, "host sha1 must be a 20-byte binary digest")
  return CacheEnvelope.MAGIC .. string.char(codecByte) .. encodeU32LE(#logicalBytes) .. digest .. compressed
end

---@param physical string
---@return boolean
function CacheEnvelope.isWrapped(physical)
  return type(physical) == "string" and physical:sub(1, 4) == CacheEnvelope.MAGIC
end

---@class CacheEnvelope.Header
---@field codec integer
---@field length integer
---@field hash string
---@field payload string

-- Parses a wrapped envelope header. Returns nil for legacy raw bytes that
-- never carried the tag; raises for a tagged but malformed header.
---@param physical string
---@return CacheEnvelope.Header?
function CacheEnvelope.parse(physical)
  assert(type(physical) == "string", "physical bytes must be a string")
  if physical:sub(1, 4) ~= CacheEnvelope.MAGIC then
    return nil
  end
  assert(#physical >= CacheEnvelope.HEADER_SIZE, "truncated envelope header")
  local codec = physical:byte(5)
  assert(CODEC_FORMATS[codec] ~= nil, "unknown envelope codec: " .. tostring(codec))
  return {
    codec = codec,
    length = decodeU32LE(physical:sub(6, 9)),
    hash = physical:sub(10, 29),
    payload = physical:sub(30),
  }
end

return CacheEnvelope
